@WebMvcTest is a **test slice annotation** in Spring Boot that loads only the parts of your application needed to test controllers.

Think of it like ordering just the appetizer instead of the full meal—you get exactly what you need to test the web layer without waiting for the entire application to boot. It loads **@Controller**, **@RestController**, **@ControllerAdvice**, **@JsonComponent**, Spring MVC configuration, and most importantly, **MockMvc**—the tool you use to simulate HTTP requests. It deliberately excludes **@Service**, **@Repository**, **@Component**, and database configuration because those belong to other layers. This makes your tests **fast** (typically under 2 seconds to start) and **focused** (if a test fails, you know it's a controller problem, not a database issue).

In production Spring Boot projects, slice tests like @WebMvcTest make up 60-70% of the test suite because they're fast, reliable, and test the API contract that clients depend on.

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService; // Service not loaded, must mock it

    @Test
    void shouldReturnOrderById() throws Exception {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderService.findById(1L)).thenReturn(Optional.of(order));

        mockMvc.perform(get("/api/orders/1")) // Simulate GET request
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.id").value(1))
               .andExpect(jsonPath("$.item").value("Laptop"));
    }
}

@WebMvcTest(ProductController.class)
class ProductControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private ProductService productService;

    @Test
    void shouldReturnProductListWithOkStatus() throws Exception {
        // Arrange: stub the service to return test data
        var products = List.of(
            new Product(1L, "Laptop", 1200.00),
            new Product(2L, "Mouse", 25.00)
        );
        when(productService.getAllProducts()).thenReturn(products);

        // Act & Assert: perform GET and verify response
        mockMvc.perform(get("/api/products"))
               .andExpect(status().isOk()) // Verify HTTP 200
               .andExpect(jsonPath("$[0].name").value("Laptop"))
               .andExpect(jsonPath("$[1].price").value(25.00));
    }
}

@WebMvcTest(UserController.class)
class UserControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService; // Service not loaded, must mock

    @MockBean
    private EmailNotificationService emailService; // Another dependency

    @Test
    void shouldCreateUserSuccessfully() throws Exception {
        var newUser = new User(null, "alice@example.com");
        var savedUser = new User(10L, "alice@example.com");

        when(userService.createUser(any(User.class))).thenReturn(savedUser);

        mockMvc.perform(post("/api/users")
               .contentType(MediaType.APPLICATION_JSON)
               .content("{\"email\":\"alice@example.com\"}"))
               .andExpect(status().isCreated())
               .andExpect(jsonPath("$.id").value(10));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper; // Injected by Spring

    @MockBean
    private OrderService orderService;

    @Test
    void shouldCreateOrderAndReturn201() throws Exception {
        var newOrder = new Order(null, "Gaming PC", 1500.00);
        var savedOrder = new Order(42L, "Gaming PC", 1500.00);

        when(orderService.createOrder(any(Order.class))).thenReturn(savedOrder);

        mockMvc.perform(post("/api/orders")
               .contentType(MediaType.APPLICATION_JSON) // Required for JSON body
               .content(objectMapper.writeValueAsString(newOrder))) // Serialize to JSON
               .andExpect(status().isCreated())
               .andExpect(jsonPath("$.id").value(42))
               .andExpect(jsonPath("$.item").value("Gaming PC"));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {
    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    @Test
    void shouldReturn404WhenOrderNotFound() throws Exception {
        var orderId = 999L;
        // Stub service to throw exception
        when(orderService.findById(orderId))
            .thenThrow(new ResourceNotFoundException("Order not found"));

        mockMvc.perform(get("/api/orders/{id}", orderId))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.message").value("Order not found"));
    }
}

@ControllerAdvice
class GlobalExceptionHandler {
    @ExceptionHandler(ResourceNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)  // Maps to 404
    public ErrorResponse handleNotFound(ResourceNotFoundException ex) {
        return new ErrorResponse(ex.getMessage());
    }
}

record ErrorResponse(String message) {}

```java
// 1) Slice test — fast, web layer only, service is mocked
@WebMvcTest(OrderController.class)
class OrderControllerSliceTest {
    @Autowired MockMvc mockMvc;
    @MockBean OrderService orderService;          // service NOT loaded -> mock it

    @Test
    void returnsOrder() throws Exception {
        when(orderService.findById(1L)).thenReturn(new Order(1L, "Laptop", 999.0));
        mockMvc.perform(get("/api/orders/1"))
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.item").value("Laptop"));
    }
}

// 2) Full integration test — real services + real DB, slower
@SpringBootTest
@AutoConfigureMockMvc                              // MockMvc not auto-added here
class OrderControllerIntegrationTest {
    @Autowired MockMvc mockMvc;                    // real OrderService + repository wired

    @Test
    void createsAndPersistsOrder() throws Exception {
        mockMvc.perform(post("/api/orders")
                 .contentType(MediaType.APPLICATION_JSON)
                 .content("{\"item\":\"Mouse\",\"price\":25.0}"))
               .andExpect(status().isCreated());    // actually saved to the database
    }
}
```

The slice test mocks the service and starts in seconds; the @SpringBootTest wires everything for a true end-to-end check.

@WebMvcTest(UserController.class)
class UserControllerTest {
    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService;

    @Test
    void shouldReturnUserWithNestedAddress() throws Exception {
        var user = new User(1L, "Alice", new Address("Seattle", "WA"));
        when(userService.findById(1L)).thenReturn(Optional.of(user));

        mockMvc.perform(get("/api/users/1"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(1))  // Root field
            .andExpect(jsonPath("$.name").value("Alice"))
            .andExpect(jsonPath("$.address.city").value("Seattle"))  // Nested object
            .andExpect(jsonPath("$.address.state").value("WA"));
    }

    @Test
    void shouldReturnOrdersArray() throws Exception {
        var orders = List.of(
            new Order(101L, "Laptop", 1200.00),
            new Order(102L, "Mouse", 25.00)
        );
        when(userService.getOrders(1L)).thenReturn(orders);

        mockMvc.perform(get("/api/users/1/orders"))
            .andExpect(jsonPath("$").isArray())  // Assert it's an array
            .andExpect(jsonPath("$[0].id").value(101))  // First element
            .andExpect(jsonPath("$[1].item").value("Mouse"))  // Second element
            .andExpect(jsonPath("$.length()").value(2));  // Array size
    }
}
